import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CvydjLy7.js";const k=JSON.parse('{"title":"消息与实时通信：Kafka、AMQP 与 WebSocket","description":"","frontmatter":{"title":"消息与实时通信：Kafka、AMQP 与 WebSocket"},"headers":[{"level":2,"title":"本篇小节","slug":"本篇小节","link":"#本篇小节","children":[]}],"relativePath":"ch08/index.md","filePath":"ch08/index.md","lastUpdated":1789497795000}'),n={name:"ch08/index.md"};function c(o,e,l,s,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="消息与实时通信-kafka、amqp-与-websocket" tabindex="-1">消息与实时通信：Kafka、AMQP 与 WebSocket <a class="header-anchor" href="#消息与实时通信-kafka、amqp-与-websocket" aria-label="Permalink to &quot;消息与实时通信：Kafka、AMQP 与 WebSocket&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本篇对应官方章节</p><p><a href="https://docs.spring.io/spring-boot/reference/messaging/index.html" target="_blank" rel="noreferrer">消息总览</a> · <a href="https://docs.spring.io/spring-boot/reference/messaging/kafka.html" target="_blank" rel="noreferrer">Kafka</a> · <a href="https://docs.spring.io/spring-boot/reference/messaging/amqp.html" target="_blank" rel="noreferrer">AMQP / RabbitMQ</a> · <a href="https://docs.spring.io/spring-boot/reference/messaging/websockets.html" target="_blank" rel="noreferrer">WebSocket</a> · <a href="https://docs.spring.io/spring-boot/reference/messaging/rsocket.html" target="_blank" rel="noreferrer">RSocket</a></p></div><p>第 7 篇让应用能主动去调别人的接口。这一篇反过来处理“别人要通知我”和“我要通知别人”的场景：活动上新了要广播给在线的浏览器，用户提交了内容要异步去建索引、发通知，这些都不该卡在 HTTP 请求里做。</p><p>这一篇与前面几篇有个根本不同：<strong>Kafka 和 RabbitMQ 都需要外部中间件</strong>。所以本篇的代码单独放一个工程 <code>activity-server-messaging</code>（端口 8082），而不是塞进 <code>activity-server</code>。理由很实际——<code>activity-server</code> 那 58 个测试能在任何一台机器上跑起来，一个中间件都不需要；把需要 broker 的代码混进去，这套“零依赖测试”就没了。</p><p>三条链路各有一个可运行的测试，全部不需要你在本机装东西：</p><table tabindex="0"><thead><tr><th>链路</th><th>测试手段</th><th>是否需要本机装中间件</th></tr></thead><tbody><tr><td>Kafka</td><td><code>@EmbeddedKafka</code> 在同 JVM 里起真 broker</td><td>否</td></tr><tr><td>RabbitMQ</td><td><code>TestRabbitTemplate</code>，不往 broker 发</td><td>否</td></tr><tr><td>WebSocket</td><td>STOMP 客户端连真实端口</td><td>否</td></tr></tbody></table><hr><h2 id="本篇小节" tabindex="-1">本篇小节 <a class="header-anchor" href="#本篇小节" aria-label="Permalink to &quot;本篇小节&quot;">​</a></h2><ul><li><a href="/backend-engineering-course/ch08/01.html">8.1 先想清楚：什么时候真的需要消息队列</a></li><li><a href="/backend-engineering-course/ch08/02.html">8.2 Kafka：依赖、配置与主题声明</a></li><li><a href="/backend-engineering-course/ch08/03.html">8.3 生产者：key 决定分区，返回的 Future 默认不等确认</a></li><li><a href="/backend-engineering-course/ch08/04.html">8.4 消费者：容器工厂、并发度与偏移量</a></li><li><a href="/backend-engineering-course/ch08/05.html">8.5 消费失败：不配的话，一条坏消息能堵死整个分区</a></li><li><a href="/backend-engineering-course/ch08/06.html">8.6 RabbitMQ：和 Kafka 不是替代关系</a></li><li><a href="/backend-engineering-course/ch08/07.html">8.7 消息转换器：Jackson 2 与 Jackson 3 在这里分岔</a></li><li><a href="/backend-engineering-course/ch08/08.html">8.8 发布确认与退回：RabbitMQ 的“发出即忘”</a></li><li><a href="/backend-engineering-course/ch08/09.html">8.9 消费者确认、prefetch 与重投</a></li><li><a href="/backend-engineering-course/ch08/10.html">8.10 WebSocket 与 STOMP：三种前缀的分工</a></li><li><a href="/backend-engineering-course/ch08/11.html">8.11 测试这三条链路</a></li><li><a href="/backend-engineering-course/ch08/12.html">8.12 选型与问题速查</a></li><li><a href="/backend-engineering-course/ch08/13.html">8.13 小结与下一步</a></li></ul>',9)])])}const g=t(n,[["render",c]]);export{k as __pageData,g as default};
